CREATE TABLE public.video_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), video_id text NOT NULL, video_title text NOT NULL, video_url text NOT NULL, thumbnail text NOT NULL DEFAULT '', reason text NOT NULL CHECK (length(trim(reason)) BETWEEN 1 AND 2000), sender_hash text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','reviewed','dismissed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(video_id,sender_hash));
GRANT SELECT, UPDATE ON public.video_reports TO authenticated;
GRANT ALL ON public.video_reports TO service_role;
ALTER TABLE public.video_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_admin_read ON public.video_reports FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY reports_admin_update ON public.video_reports FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_hash text NOT NULL, user_id uuid, sender_name text NOT NULL CHECK (length(trim(sender_name)) BETWEEN 1 AND 80), subject text NOT NULL CHECK (length(trim(subject)) BETWEEN 1 AND 160), kind text NOT NULL CHECK (kind IN ('question','part','series','suggestion')), video_id text, video_title text, video_url text, thumbnail text NOT NULL DEFAULT '', admin_unread integer NOT NULL DEFAULT 1, sender_unread integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.contact_conversations TO authenticated;
GRANT ALL ON public.contact_conversations TO service_role;
ALTER TABLE public.contact_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY contact_admin_read ON public.contact_conversations FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.contact_conversations(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('sender','admin')), text text NOT NULL CHECK (length(trim(text)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.contact_messages TO authenticated;
GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_admin_read ON public.contact_messages FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY messages_admin_reply ON public.contact_messages FOR INSERT TO authenticated WITH CHECK (role = 'admin' AND public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX contact_message_duplicates ON public.contact_messages(conversation_id,role,md5(text));
CREATE UNIQUE INDEX contact_conversation_duplicates ON public.contact_conversations(sender_hash,md5(subject),kind,coalesce(video_id,''));
CREATE TABLE public.support_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, target_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_activity TO authenticated;
GRANT ALL ON public.support_activity TO service_role;
ALTER TABLE public.support_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_activity_admin_read ON public.support_activity FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.support_message_saved() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
UPDATE public.contact_conversations SET updated_at=now(), admin_unread=CASE WHEN NEW.role='sender' THEN admin_unread+1 ELSE admin_unread END, sender_unread=CASE WHEN NEW.role='admin' THEN sender_unread+1 ELSE sender_unread END WHERE id=NEW.conversation_id;
IF NEW.role='admin' THEN INSERT INTO public.support_activity(actor_id,action,target_id) VALUES(auth.uid(),'admin_reply',NEW.conversation_id::text); END IF;
RETURN NEW; END $$;
CREATE TRIGGER support_message_saved AFTER INSERT ON public.contact_messages FOR EACH ROW EXECUTE FUNCTION public.support_message_saved();
CREATE FUNCTION public.support_video_deleted() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.support_activity(actor_id,action,target_id,details) VALUES(auth.uid(),'video_deleted',OLD.id,jsonb_build_object('title',OLD.title)); RETURN OLD; END $$;
CREATE TRIGGER support_video_deleted AFTER DELETE ON public.videos FOR EACH ROW EXECUTE FUNCTION public.support_video_deleted();
CREATE FUNCTION public.support_report_action(p_id uuid,p_action text,p_confirmed boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.video_reports; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT * INTO r FROM public.video_reports WHERE id=p_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Report unavailable'; END IF;
IF p_action='delete' THEN IF NOT p_confirmed THEN RAISE EXCEPTION 'Confirmation required'; END IF; DELETE FROM public.videos WHERE id=r.video_id; UPDATE public.video_reports SET status='reviewed' WHERE id=p_id;
ELSIF p_action IN ('reviewed','dismissed') THEN UPDATE public.video_reports SET status=p_action WHERE id=p_id; ELSE RAISE EXCEPTION 'Invalid action'; END IF;
INSERT INTO public.support_activity(actor_id,action,target_id,details) VALUES(auth.uid(),'report_'||p_action,p_id::text,jsonb_build_object('video_id',r.video_id));
END $$;
REVOKE ALL ON FUNCTION public.support_report_action(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.support_report_action(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.support_admin_read(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.contact_conversations SET admin_unread=0 WHERE id=p_id; END $$;
REVOKE ALL ON FUNCTION public.support_admin_read(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.support_admin_read(uuid) TO authenticated;